function numeric(v,min,max,fallback){return typeof v==='number'&&Number.isFinite(v)?clamp(Math.floor(v),min,max):fallback}
function validateCharacter(raw){if(!raw||typeof raw!=='object')throw Error('ข้อมูลตัวละครไม่ถูกต้อง');const p=fresh();for(const k of ['level','xp','ap','sp','str','dex','vit','int','hp','mp','crystals','kills','cleared']){if(typeof raw[k]!=='number'||!Number.isFinite(raw[k]))throw Error('ค่า '+k+' ไม่ถูกต้อง');p[k]=numeric(raw[k],k==='level'?1:0,k==='cleared'?3:k==='level'||['str','dex','vit','int'].includes(k)?999:999999999,p[k])}if(!raw.skills)throw Error('ไม่มีข้อมูลสกิล');for(const k of ['heal','haste','light']){if(!Number.isInteger(raw.skills[k])||raw.skills[k]<0||raw.skills[k]>5)throw Error('ข้อมูลสกิลไม่ถูกต้อง');p.skills[k]=Math.max(1,raw.skills[k])}if(raw.job!==undefined&&!Object.hasOwn(JOBS,raw.job))throw Error('อาชีพไม่ถูกต้อง');p.job=raw.job||'swordsman';if(raw.promotionTokens!==undefined&&(!Number.isInteger(raw.promotionTokens)||raw.promotionTokens<0||raw.promotionTokens>1))throw Error('ไอเทมเปลี่ยนอาชีพไม่ถูกต้อง');p.promotionTokens=raw.promotionTokens||0;if(raw.luk!==undefined&&(typeof raw.luk!=='number'||!Number.isFinite(raw.luk)||raw.luk<0))throw Error('ค่า luk ไม่ถูกต้อง');p.luk=raw.luk===undefined?5:numeric(raw.luk,0,999,5);p.special=validateSpecial(raw.special);p.swordSkills=validateSwordSkills(raw.swordSkills);if(legacySwordSkills(raw.swordSkills))p.sp+=(raw.swordSkills.powerBash||0);p.skillVersion=2;if(raw.spVersion!==undefined&&raw.spVersion!==1&&raw.spVersion!==2)throw Error('เวอร์ชันแต้มสกิลไม่ถูกต้อง');if(raw.spVersion!==2)p.sp+=2*Math.min(29,Math.max(0,p.level-1));p.spVersion=2;p.skillSlots=validateSkillSlots(raw.skillSlots,p.swordSkills);p.consumables=validateConsumables(raw.consumables);p.loot=validateLoot(raw.loot);p.name=typeof raw.name==='string'?raw.name.slice(0,24):'Fern';return p}
function legacyCharacter(data){if(data?.game!=='Fernvale'||data.version!==1||!data.player)throw Error('ไม่ใช่เซฟ Fernvale');const p={...data.player,cleared:data.stages?.cleared||0};return validateCharacter(p)}
function readStorage(){try{settings={...settings,...JSON.parse(localStorage.getItem(SETTINGS_KEY)||'{}')};settings.sound=!!settings.sound;settings.volume=typeof settings.volume==='number'?clamp(settings.volume,0,1):.5}catch{}try{const raw=localStorage.getItem(SAVE_KEY);if(raw){unreadableSave=raw;const data=JSON.parse(raw);if(data.game!=='Fernvale'||data.version!==2||!Array.isArray(data.slots)||data.slots.length!==3)throw Error('รูปแบบเซฟไม่ถูกต้อง');slots=data.slots.map(s=>s?{character:validateCharacter(s.character),savedAt:String(s.savedAt||'')}:null);unreadableSave=null;return}for(const key of ['fernvale.godot.web.v1','fernvale.save.v1']){const legacy=localStorage.getItem(key);if(legacy){try{slots[0]={character:legacyCharacter(JSON.parse(legacy)),savedAt:new Date().toISOString()};persist();$('saveMessage').textContent='ย้ายเซฟเดิมมาไว้ช่อง 01 แล้ว · เซฟต้นฉบับยังเก็บอยู่';return}catch{}}}}catch{storageReadOnly=true;$('saveMessage').textContent='อ่านเซฟไม่ได้ — เก็บข้อมูลเดิมไว้แล้ว ใช้สำรองเซฟก่อนนำเข้าไฟล์ที่ถูกต้อง';toast('อ่านเซฟไม่ได้ ข้อมูลเดิมจะไม่ถูกเขียนทับ')}}
function snapshot(){const p={};for(const k of Object.keys(fresh()))p[k]=k==='loot'?structuredClone(player.loot):['skills','special','swordSkills','skillSlots','consumables'].includes(k)?{...player[k]}:player[k];return p}
function bundle(){return {game:'Fernvale',version:2,slots,savedAt:new Date().toISOString()}}
function persist(){if(storageReadOnly)return false;try{localStorage.setItem(SAVE_KEY,JSON.stringify(bundle()));saveWarning=false;return true}catch{if(!saveWarning)toast('เซฟในเบราว์เซอร์ไม่ได้ กรุณาสำรองเซฟเป็นไฟล์');saveWarning=true;return false}}
