function switchScreen(next){if(!$('characterOverlay').hidden)closeCharacterWindow();screen=next;paused=next!=='play';keys={};for(const [id,s]of [['titleScreen','title'],['savesScreen','saves'],['creatorScreen','creator'],['playScreen','play'],['stagesScreen','stages']])$(id).hidden=s!==next;if(next==='saves')renderSlots();if(next==='stages')renderStages();if(next==='play')canvas.focus({preventScroll:true})}
function modal(title,body,actions){hideUpgradeTooltip();$('modal').classList.remove('shop-modal','skill-modal');let close=$('modalCloseBtn');if(!close){close=document.createElement('button');close.id='modalCloseBtn';close.className='window-close';close.textContent='×';close.setAttribute('aria-label','ปิดหน้าต่าง');$('modal').querySelector('.dialog-card').prepend(close)}close.onclick=closeModal;keys={};paused=true;$('modalTitle').textContent=title;$('modalBody').replaceChildren();if(typeof body==='string'){const p=document.createElement('p');p.textContent=body;$('modalBody').append(p)}else $('modalBody').append(body);$('modalButtons').replaceChildren();for(const [label,fn,primary]of actions){if(fn===closeModal)continue;const b=document.createElement('button');b.textContent=label;if(primary)b.className='primary';b.onclick=fn;$('modalButtons').append(b)}$('modal').hidden=false;$('modalButtons').querySelector('button')?.focus()}
function closeModal(){if(tradeOverlay){closeTradePopup();return}hideUpgradeTooltip();saleSelections.clear();controlWindow=null;$('modal').classList.remove('skill-modal','shop-modal'); $('modal').hidden=true;paused=screen!=='play'||!!run?.finished||!$('characterOverlay').hidden;keys={};if(!paused)canvas.focus({preventScroll:true})}
function renderSlots(){$('slots').replaceChildren();slots.forEach((s,i)=>{const row=document.createElement('div');row.className='slot-row';const b=document.createElement('button');b.className='slot-main';const number=document.createElement('span');number.className='slot-num';number.textContent=String(i+1).padStart(2,'0');const info=document.createElement('span');info.className='slot-info';const strong=document.createElement('strong'),small=document.createElement('small');strong.textContent=s?`${s.character.name} · Lv. ${s.character.level}`:'NO DATA';small.textContent=s?`${JOBS[s.character.job||'swordsman'].name} · ผ่าน ${s.character.cleared} / 3 ด่าน`:'ช่องว่าง · เริ่มการผจญภัยใหม่';info.append(strong,small);const arrow=document.createElement('span');arrow.textContent=s?'เล่นต่อ →':'สร้างตัวละคร →';b.append(number,info,arrow);b.onclick=()=>slots[i]?loadSlot(i):openCreator(i);row.append(b);if(s){const del=document.createElement('button');del.className='delete-save';del.setAttribute('aria-label','ลบเซฟช่อง '+(i+1));del.title='ลบเซฟช่อง '+(i+1);del.innerHTML='<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></svg>';del.disabled=storageReadOnly;del.onclick=()=>deleteSlot(i);row.append(del)}$('slots').append(row)})}
function resetMotion(){swordSwipes=[];player.airLeapUsed=false;player.upperUsed=false;player.diving=null;player.dashV=0;player.dashTime=0;player.vx=player.vy=player.haste=player.swing=player.dropThrough=0;player.ground=platforms.some(p=>player.x>=p.x&&player.x<=p.x+p.w&&Math.abs(player.y-p.y)<.2);player.climbing=false;player.invuln=2;player.cd={heal:0,haste:0,light:0,attack:0,hpPotion:0,mpPotion:0};keys={};shots=[];effects=[];texts=[];drops=[];portalCooldown=1;saveTimer=0}
function loadSlot(i){if(!slots[i])return openCreator(i);activeSlot=i;Object.assign(player,slots[i]?validateCharacter(slots[i].character):fresh());player.hp=clamp(player.hp,1,maxHP());player.mp=clamp(player.mp,0,maxMP());gainXP(0);enterTown();save();if(!saveWarning&&!storageReadOnly)toast(slots[i]?'การผจญภัยเริ่มแล้ว · Spacebar เข้าแสงวาร์ป':'ยินดีต้อนรับ')}
function enterTown(){interactables=[{kind:'npc',x:335,y:290,radius:48,action:openPotionShop},{kind:'portal',x:1050,y:170,radius:65,action:openStages}];run=null;player.map='town';platforms=[{x:0,y:420,w:1280},{x:0,y:290,w:380},{x:820,y:170,w:460}];ladders=[{x:900,top:170,bottom:420}];player.x=210;player.y=290;resetMotion();monsters=[];camera=0;$('resultOverlay').hidden=true;$('stageBtn').textContent='เลือกด่าน';switchScreen('play');updateUI()}
function beginStage(id){const trial=id===4;if(trial?!canEnterTrial():!canEnterDungeon(id))return;const s=trial?TRIAL:stageById(id);interactables=[];run={id,trial,total:s.count,kills:0,time:0,pendingXP:0,combo:0,maxCombo:0,lastKill:-99,comboPoints:0,eliteKills:0,bossKills:0,eliteSpawns:0,eliteProgress:0,finished:false,serial:++runSerial};player.map='forest';platforms=[{x:0,y:420,w:1200},{x:140,y:300,w:980},{x:60,y:180,w:980}];ladders=[{x:1070,top:300,bottom:420},{x:210,top:180,bottom:300}];if(trial){platforms=[{x:0,y:420,w:960}];ladders=[];}player.x=110;player.y=420;resetMotion();camera=0;monsters=[];for(let i=0;i<s.count;i++){const lane=i%3,p=platforms[lane],index=Math.floor(i/3),count=Math.ceil((s.count-lane)/3),low=lane?p.x+42:235,high=p.x+p.w-45,boss=trial;const x=trial?650:low+(high-low)*index/Math.max(1,count-1);monsters.push({id:i,level:s.level,x,y:p.y,p:lane,home:x,low:trial?350:low,high:trial?880:high,dir:i%2?1:-1,hp:s.hp*(boss&&!trial?4:1),max:s.hp*(boss&&!trial?4:1),atk:s.atk*(boss&&!trial?1.5:1),def:s.def,avoid:s.avoid,exp:s.exp*(boss&&!trial?5:1),dead:0,hit:0,phase:random(0,6),boss})}$('resultOverlay').hidden=true;$('stageBtn').textContent='กลับหมู่บ้าน';switchScreen('play');if(id===0)setupTutorial();updateUI();save()}
function renderStoryStages(){$('stageList').replaceChildren();STAGES.forEach(s=>{const b=document.createElement('button');b.className='stage-row';b.disabled=!canEnterDungeon(s.id);b.title=b.disabled?'ต้องมีเลเวล '+requiredStageLevel(s):s.name;b.innerHTML=`<span><small>STAGE ${s.id}</small><strong class="stage-name">${s.name}</strong></span><span class="stage-level">Lv. ${s.level}</span><span class="portraits"><span class="portrait"><canvas width="44" height="44" aria-label="มอสสไลม์"></canvas>มอสสไลม์</span><span class="portrait"><canvas width="44" height="44" aria-label="Elite สไลม์"></canvas>Elite</span></span>`;b.onclick=()=>beginStage(s.id);$('stageList').append(b);b.querySelectorAll('canvas').forEach((c,i)=>{const g=c.getContext('2d');g.imageSmoothingEnabled=false;g.fillStyle=i?'#536d3c':'#85b771';g.fillRect(9,21,26,16);g.fillRect(13,13,18,22);g.fillStyle='#d6e5a6';g.fillRect(14,15,7,4);g.fillStyle='#213d2d';g.fillRect(16,25,3,4);g.fillRect(27,25,3,4);if(i){g.fillStyle='#e0bd68';g.fillRect(5,39,34,3)}})})}

function gainXP(amount){player.xp+=amount;while(player.xp>=needXP()&&player.level<999){player.xp-=needXP();player.level++;player.ap+=5;player.sp+=player.level<=ADVANCEMENT_LEVEL?3:1;player.hp=maxHP();player.mp=maxMP();floatText(player.x,player.y-70,'LEVEL UP!','#fff2b0',24);tone(880,.4)}if(player.level===999)player.xp=Math.min(player.xp,needXP()-1)}
function monsterHitChance(stats,m){return clamp(stats.acc-(m.avoid||0),5,100)}
function hitMonster(m,base){if(m.dead||run?.finished)return false;const stats=characterStatus();if(Math.random()*100>=monsterHitChance(stats,m)){floatText(m.x,m.y-monsterHeight(m)-10,'MISS','#b4c3cc');return false}const crit=Math.random()<stats.cri/100,damage=Math.max(1,Math.round(base*random(.9,1.1)*(crit?stats.criDamage/100:1)*(1+(stats.damage+(m.boss?stats.bossDamage:0))/100)*(1-clamp((m.def||0)/100*(1-stats.ignoreDef/100),0,.95))));m.hp=Math.max(0,m.hp-damage);m.hit=.2;floatText(m.x,m.y-42,(crit?'CRIT ':'')+damage,crit?'#ffcf66':'#fff7d4');burst(m.x,m.y-15,'#d3e7a3',6);tone(220,.07,'triangle');if(m.hp===0){m.dead=1;player.kills++;run.kills++;recordKill(m);if(run.trial&&m.boss)finishStage(true,'clear')}return true}
function finishStage(won,reason=won?'clear':'defeat'){
 if(!run||run.finished)return;
 run.finished=true;paused=true;keys={};shots=[];drops=[];toastTimer=0;$('toast').classList.remove('show');
 const result=calculateResult(run);run.result=result;
 const beforeLevel=player.level;result.beforeXP=player.xp;result.beforeLevel=beforeLevel;
 gainXP(run.tutorial?0:result.bonusXP);
 if(won){if(run.trial)player.promotionTokens=1;else player.cleared=Math.max(player.cleared,run.id)}
 result.loot=grantRoundLoot(won);save();
 $('resultEyebrow').textContent='ROUND RESULTS';
 $('resultTitle').textContent=reason==='timeout'?'ครบเวลา 3 นาที':reason==='leave'?'จบการฟาร์ม':won?'ผ่านบททดสอบแล้ว':'หมดแรงแล้ว';
 $('resultDetail').textContent=`${Math.floor(run.time/60)}:${String(Math.floor(run.time%60)).padStart(2,'0')} นาที · ${won?'ผ่านด่านแล้ว':'สรุปคะแนนรอบนี้'}${won&&run.trial?' · ผ่านภารกิจเปลี่ยนอาชีพแล้ว':''}`;
 renderRoundResult(result,beforeLevel);
 $('retryBtn').hidden=true;$('resultOverlay').hidden=false;
 $('resultTownBtn').focus();updateUI();
}
function act(action){if(paused||screen!=='play'||['heal','haste','light'].includes(action))return;if(action==='pickup')return;if(action==='attack'){if(player.cd.attack>0)return;player.cd.attack=jobProfile().cooldown;player.swing=.25;tone(135,.08,'sawtooth',.018);const target=monsters.filter(m=>{const dx=(m.x-player.x)*player.face;return !m.dead&&dx>-(monsterRadius(m)+10)&&dx<jobProfile().reach+monsterRadius(m)&&player.y>m.y-monsterHeight(m)-15&&player.y<m.y+46}).sort((a,b)=>Math.abs(a.x-player.x)-Math.abs(b.x-player.x))[0];if(target)hitMonster(target,attackPower()*jobProfile().multiplier);return}if(!['heal','haste','light'].includes(action)||player.cd[action]>0)return;const lv=player.skills[action],cost=action==='heal'?12:action==='haste'?10:8;if(player.mp<cost||action==='heal'&&player.hp>=maxHP())return;player.mp-=cost;if(action==='heal'){const value=Math.min(maxHP()-player.hp,25+lv*18+player.int*2);player.hp+=value;player.cd.heal=7;floatText(player.x,player.y-50,'+'+value+' HP','#b4ffad');burst(player.x,player.y-20,'#bdffa9',20);tone(620,.3)}if(action==='haste'){player.haste=8+lv*2;player.cd.haste=18;tone(490,.2)}if(action==='light'){player.cd.light=Math.max(.45,1.25-lv*.1);shots.push({x:player.x+player.face*24,y:player.y-24,vx:player.face*620,life:1,damage:18+lv*12+attackPower()});tone(930,.14,'triangle')}updateUI()}
function openStages(){save();switchScreen('stages')}
function returnTown(){if(run&&!run.finished){modal('จบการฟาร์ม?','EXP จากมอนสเตอร์ได้รับแล้ว จบรอบเพื่อรับโบนัสคะแนนและรางวัล',[['เล่นต่อ',closeModal],['จบรอบและดูผล',()=>{closeModal();finishStage(!run.trial&&run.kills>0,'leave')},true]])}else{enterTown();save()}}
function interact(){if(paused||screen!=='play')return false;const target=interactables.filter(t=>Math.abs(player.x-t.x)<(t.radius||65)&&Math.abs(player.y-t.y)<48).sort((a,b)=>Math.abs(player.x-a.x)-Math.abs(player.x-b.x))[0];if(!target)return false;if(portalCooldown<=0){portalCooldown=.4;keys={};target.action()}return true}

function jump(){if(keys.ArrowDown&&player.ground&&player.y<419){player.dropThrough=.3;player.y+=3;player.vy=90;player.ground=false;player.climbing=false;return}if(player.ground||player.climbing){tutorialMark('jump');player.vy=-445*(1+(player.swordSkills.warriorMastery||0)*.02);player.ground=false;player.climbing=false;player.y-=2;tone(270,.09,'triangle',.02)}else castSwordSkill('warriorLeap')}
function update(dt){if(paused||screen!=='play')return;tickSwordSwipes(dt);time+=dt;if(run){run.time+=dt;updateRound(dt)}portalCooldown=Math.max(0,portalCooldown-dt);for(const k of ['invuln','swing','haste','dropThrough'])player[k]=Math.max(0,player[k]-dt);for(const k in player.cd)player.cd[k]=Math.max(0,player.cd[k]-dt);const move=(keys.ArrowRight?1:0)-(keys.ArrowLeft?1:0),up=keys.ArrowUp,down=keys.ArrowDown;player.vx=player.dashTime>0?player.dashV:move*155*(1+(player.swordSkills.warriorMastery||0)*.03)*(player.haste>0?1.35+player.skills.haste*.08:1);if(move)player.face=move;const ladder=ladders.find(l=>Math.abs(player.x-l.x)<=36&&player.y>=l.top-5&&player.y<=l.bottom+5);const climbDirection=(down?1:0)-(up?1:0);if(ladder&&!player.dropThrough&&((climbDirection<0&&player.y>ladder.top)||(climbDirection>0&&player.y<ladder.bottom))){player.climbing=true;player.ground=false;player.dropThrough=0;player.vx=0;player.x=ladder.x;player.vy=(down?1:-1)*125;player.y+=player.vy*dt;if(player.y<=ladder.top){player.y=ladder.top;player.climbing=false;player.ground=true;player.vy=0}else if(player.y>=ladder.bottom){player.y=ladder.bottom;player.climbing=false;player.ground=true;player.vy=0}}else if(player.climbing&&!move){player.vy=0}else{player.climbing=false;const oldY=player.y,oldX=player.x,wasGround=player.ground;player.x=clamp(player.x+player.vx*dt,22,worldWidth()-22);player.vy+=GRAVITY*dt;player.y+=player.vy*dt;player.ground=false;const candidates=platforms.filter(p=>(p.y===420||!player.dropThrough)&&player.x>=p.x-5&&player.x<=p.x+p.w+5&&oldY<=p.y+.2&&player.y>=p.y).map(p=>p.y);if(player.map==='town'&&!player.dropThrough&&player.x>=380&&player.x<=680){const sy=290+(player.x-380)/300*130,oldSlope=290+(clamp(oldX,380,680)-380)/300*130;if((oldY<=sy+1&&player.y>=sy)||(wasGround&&Math.abs(oldY-oldSlope)<4)){candidates.push(sy)}}if(player.map==='town'&&!player.dropThrough&&wasGround&&oldX>=380&&oldX<390&&player.x<380&&Math.abs(oldY-(290+(oldX-380)/300*130))<2)candidates.push(290);if(player.vy>=0&&candidates.length){player.y=Math.min(...candidates);player.vy=0;player.ground=true}}
if(keys.KeyC)act('attack');if(paused)return;
for(const m of monsters){if(m.dead)continue;m.hit=Math.max(0,m.hit-dt);m.x+=m.dir*(m.hit?0:m.boss?40:32)*dt;if(m.x<m.low||m.x>m.high){m.x=clamp(m.x,m.low,m.high);m.dir*=-1}if(Math.abs(m.x-player.x)<monsterRadius(m)+12&&player.y>m.y-monsterHeight(m)&&player.y<m.y+36&&player.invuln<=0){const damage=Math.max(1,Math.round((m.atk-defense())*(1-(player.swordSkills.ironBody||0)*.005)));player.hp-=damage;player.invuln=1.2;floatText(player.x,player.y-50,'-'+damage,'#ffb7a2');if(Math.random()>=(player.swordSkills.warriorMastery||0)*.02)player.x=clamp(player.x+(player.x<m.x?-18:18),22,worldWidth()-22);tone(100,.1);if(player.hp<=0){player.hp=0;finishStage(false);return}}}
for(const s of shots){const old=s.x;s.x+=s.vx*dt;s.life-=dt;const hits=monsters.filter(m=>!m.dead&&m.x>=Math.min(old,s.x)-monsterRadius(m)&&m.x<=Math.max(old,s.x)+monsterRadius(m)&&s.y>=m.y-monsterHeight(m)&&s.y<=m.y+5).sort((a,b)=>Math.abs(a.x-old)-Math.abs(b.x-old));if(hits.length){hitMonster(hits[0],s.damage);s.life=0}}shots=shots.filter(s=>s.life>0);for(const f of effects){f.life-=dt;f.x+=f.vx*dt;f.y+=f.vy*dt;f.vy+=180*dt}effects=effects.filter(f=>f.life>0);for(const f of texts){f.life-=dt;f.y-=30*dt}texts=texts.filter(f=>f.life>0);player.hp=Math.min(maxHP(),player.hp+(player.map==='town'?6*dt:0));player.mp=Math.min(maxMP(),player.mp+(player.map==='town'?5:2)*dt);camera+=(clamp(player.x-W*.42,0,worldWidth()-W)-camera)*Math.min(1,dt*7);updateTutorial();saveTimer+=dt;if(saveTimer>8){saveTimer=0;save()}updateUI()}
function drawWorld(){const town=player.map==='town';rect(0,0,W,H,town?'#b7d9d0':'#a9cec0');ellipse(760-camera*.03,65,30,30,'#f4e8b7');for(let i=-1;i<9;i++){const x=i*230-camera*.16;poly([[x-100,350],[x+40,130+(i%3)*23],[x+230,350]],'#91b79f');poly([[x,370],[x+120,190],[x+260,370]],'#a2c5ad')}for(let i=-1;i<18;i++)tree(i*180-camera*.28,390,.72+(i%3)*.1,1);ctx.save();ctx.translate(-Math.round(camera),0);if(town){house(130,290,.68,'#bd795f');house(295,290,.56,'#c89569');tree(20,290,.82);tree(790,420,.75);tree(1210,170,.65);}drawTerrain();if(run?.tutorial)drawTutorialSign();if(town){portal(1050,170);drawPotionMerchant()}else{for(const m of monsters)if(!m.dead&&m.x>camera-100&&m.x<camera+W+100){if(m.elite){ctx.save();ctx.translate(m.x,m.y);ctx.scale(3,3);drawSlime({...m,x:0,y:0});ctx.restore();ctx.font='bold 12px monospace';ctx.textAlign='center';ctx.fillStyle='#ffe198';ctx.fillText('ELITE',m.x,m.y-124)}else if(m.boss){ctx.save();ctx.translate(m.x,m.y);ctx.scale(1.55,1.55);drawSlime({...m,x:0,y:0});rect(-10,-35,20,5,'#dfbd6a');rect(-10,-40,4,6,'#dfbd6a');rect(-2,-42,4,8,'#dfbd6a');rect(6,-40,4,6,'#dfbd6a');ctx.restore()}else drawSlime(m)}}
for(const l of ladders)ladderDraw(l);for(const d of drops){const y=d.baseY+Math.sin(time*3+d.x)*3;poly([[d.x,y-12],[d.x+7,y-5],[d.x,y+4],[d.x-7,y-5]],'#aee1ce');rect(d.x-2,y-9,3,7,'#ecffdb')}drawPlayer();drawSwordSwipes();for(const s of shots){rect(s.x-20*Math.sign(s.vx),s.y-2,25,4,'#f7d987');rect(s.x-5,s.y-5,10,10,'#fff4c9')}for(const f of effects){ctx.globalAlpha=clamp(f.life*3,0,1);rect(f.x,f.y,f.size,f.size,f.color)}ctx.globalAlpha=1;for(const f of texts){ctx.globalAlpha=clamp(f.life*2,0,1);ctx.font='bold '+f.size+'px monospace';ctx.textAlign='center';ctx.strokeStyle='#365342';ctx.lineWidth=3;ctx.strokeText(f.text,f.x,f.y);ctx.fillStyle=f.color;ctx.fillText(f.text,f.x,f.y)}ctx.globalAlpha=1;ctx.restore();drawMinimap()}
function drawMinimap(){rect(14,16,132,82,'#050a07');rect(18,20,124,18,'#ffffff');ctx.font='9px Thai,Tahoma,sans-serif';ctx.textAlign='center';ctx.fillStyle='#172b20';ctx.fillText(player.map==='town'?'หมู่บ้านเฟิร์นเวล':(run?.trial?TRIAL:stageById(run?.id??0)).name,80,33,117);const scale=112/worldWidth();for(const p of platforms)rect(24+p.x*scale,43+p.y/480*43,p.w*scale,2,'#a9bb88');for(const m of monsters)if(!m.dead)rect(24+m.x*scale,42+m.y/480*43,2,2,m.elite?'#edb674':'#d4cd87');rect(24+player.x*scale,41+player.y/480*43,3,3,'#ffffff')}

function updateUI(){updateCombatMeters();updateSwordHUD();$('careerBtn').hidden=player.map!=='town';$('level').textContent=player.level;for(const[k,value,max]of [['hp',player.hp,maxHP()],['mp',player.mp,maxMP()],['xp',player.xp,needXP()]]){$(k+'Fill').style.width=clamp(value/max*100,0,100)+'%';$(k+'Text').textContent=(k==='xp'?'EXP':k.toUpperCase())+' '+Math.floor(value)+' / '+max}$('lootCount').textContent=JOBS[player.job].name+(player.promotionTokens?' · ตรานักรบ 1':'')+' · เซฟ '+(activeSlot+1);$('mapType').textContent=player.map==='town'?'SAFE VILLAGE':'STAGE '+run?.id;$('mapName').textContent=player.map==='town'?'หมู่บ้านเฟิร์นเวล':(run?.trial?TRIAL:stageById(run?.id??0)).name;$('runProgress').textContent=run?'กำจัด '+run.kills+' · COMBO '+run.combo:'';$('worldHint').textContent=player.haste>0?'วิ่งเร็ว · '+player.haste.toFixed(1)+' วิ':player.map==='town'?'Spacebar เลือกด่าน · ↓ + Space ลงชั้นล่าง':'C ฟัน · ↑ ↓ ปีน · ↓ + Space ลงชั้นล่าง'}
function pauseGame(){if(screen!=='play'||run?.finished)return;save();modal('พักการผจญภัย','เกมหยุดอยู่ ความคืบหน้าบันทึกในเซฟช่อง '+(activeSlot+1),[['เล่นต่อ',closeModal,true],['สำรองเซฟ',()=>download(bundle(),'Fernvale-saves.json')],['ตั้งค่า',openSettings],...(player.map==='town'?[['เลือกด่าน',()=>{closeModal();openStages()}],['เส้นทางอาชีพ',()=>{closeModal();openCareer()}]]:[['จบรอบ',()=>{closeModal();returnTown()}]]),['เลือกตัวละคร',()=>{closeModal();if(run&&!run.finished){finishStage(!run.trial&&run.kills>0,'leave');return}save();activeSlot=-1;switchScreen('saves')}]])}
function openSettings(){const body=document.createElement('div');body.innerHTML='<label><input id="soundToggle" type="checkbox"> เปิดเสียงเอฟเฟกต์</label><label>ระดับเสียง <input id="volumeInput" type="range" min="0" max="100" aria-label="ระดับเสียง"></label><h3>การควบคุม</h3><dl class="controls-list"><dt>เดิน</dt><dd>← / →</dd><dt>กระโดด / โต้ตอบ</dt><dd>Spacebar</dd><dt>ช่องสกิล</dt><dd>Q / W / E / R</dd><dt>Status</dt><dd>Tab</dd><dt>Skill</dt><dd>1</dd><dt>Party</dt><dd>2</dd><dt>Enchant</dt><dd>3</dd><dt>ปีนบันได</dt><dd>↑ / ↓</dd><dt>โจมตีดาบ</dt><dd>C</dd><dt>ยา HP / MP</dt><dd>Z / X</dd></dl>';modal('ตั้งค่า',body,[['บันทึกและกลับ',()=>{settings.sound=$('soundToggle').checked;settings.volume=Number($('volumeInput').value)/100;try{localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings))}catch{}closeModal();tone(650,.15)},true]]);$('soundToggle').checked=settings.sound;$('volumeInput').value=settings.volume*100}
$('startBtn').onclick=()=>switchScreen('saves');document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>switchScreen('title'));document.querySelectorAll('[data-settings]').forEach(b=>b.onclick=openSettings);$('exitBtn').onclick=()=>modal('ออกจากเกม','ปิดแท็บเบราว์เซอร์นี้เพื่อออกจากเกม',[['กลับหน้าแรก',closeModal,true]]);$('stageBtn').onclick=()=>player.map==='town'?openStages():returnTown();$('stagesBack').onclick=()=>{switchScreen('play');updateUI()};$('pauseBtn').onclick=pauseGame;$('retryBtn').onclick=()=>{player.hp=maxHP();player.mp=maxMP();beginStage(run.id)};$('resultTownBtn').onclick=()=>{const advance=!!run?.trial&&player.promotionTokens>0;player.hp=maxHP();enterTown();save();if(advance)openCareer()};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));$('exportAllBtn').onclick=()=>download(storageReadOnly&&unreadableSave!==null?unreadableSave:bundle(),storageReadOnly?'Fernvale-recovery.json':'Fernvale-saves.json');
$('importBtn').onclick=()=>{$('importFile').value='';$('importFile').click()};$('importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw Error('ไฟล์ใหญ่เกินไป');const data=JSON.parse(await file.text());let pending;if(data.game==='Fernvale'&&data.version===2&&Array.isArray(data.slots)&&data.slots.length===3){pending=data.slots.map(s=>s?{character:validateCharacter(s.character),savedAt:new Date().toISOString()}:null)}else{const p=legacyCharacter(data);const index=slots.findIndex(s=>!s);if(index<0)throw Error('เซฟเต็มทั้ง 3 ช่อง กรุณาสำรองก่อนนำเข้าชุดเซฟใหม่');pending=slots.map((s,i)=>i===index?{character:p,savedAt:new Date().toISOString()}:s)}modal('นำเข้าเซฟ?','ข้อมูลเซฟจะเปลี่ยนตามไฟล์นี้ กรุณาสำรองเซฟปัจจุบันก่อนยืนยัน',[['ยกเลิก',closeModal],['สำรองปัจจุบัน',()=>download(bundle(),'Fernvale-backup.json')],['ยืนยันนำเข้า',()=>{slots=pending;storageReadOnly=false;unreadableSave=null;const stored=persist();closeModal();renderSlots();$('saveMessage').textContent=stored?'นำเข้าเซฟและบันทึกในเบราว์เซอร์แล้ว':'นำเข้าแล้ว แต่เบราว์เซอร์บันทึกไม่ได้ กรุณาสำรองเป็นไฟล์';toast(stored?'นำเข้าเซฟแล้ว':'นำเข้าแล้ว กรุณาสำรองไฟล์ก่อนปิดหน้า')},true]])}catch(e){toast('นำเข้าไม่ได้: '+e.message)}};
const gameKeys=['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space','KeyX','KeyC','KeyZ','KeyQ','KeyW','KeyR','KeyE'];function press(code,repeat=false){if(paused||screen!=='play')return;keys[code]=true;if(!repeat){if(code==='Space'&&!interact())jump();if(code==='KeyZ')usePotion('hp');if(code==='KeyX')usePotion('mp');const slot={KeyQ:'q',KeyW:'w',KeyE:'e',KeyR:'r'}[code];if(slot)castAssignedSkill(slot);if(code==='KeyC'){if(keys.ArrowUp&&castSwordSkill('upperCharge'))return;if(keys.ArrowDown&&!player.ground&&castSwordSkill('leapAttack'))return;act('attack')}}}window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(handleWindowShortcut(e))return;if(e.code==='Tab'&&screen==='play'&&($('modal').hidden)&&!run?.finished){e.preventDefault();if(!e.repeat)toggleCharacterWindow();return}if(!$('characterOverlay').hidden){if(e.code==='Escape'){e.preventDefault();closeCharacterWindow()}return}if(['Escape','KeyP'].includes(e.code)){if(!e.repeat){if(!$('modal').hidden)closeModal();else if(screen==='play')pauseGame();else if(screen==='stages')switchScreen('play');else if(screen==='creator')leaveCreator()}return}if(screen!=='play'||paused)return;if(gameKeys.includes(e.code))e.preventDefault();press(e.code,e.repeat)});window.addEventListener('keyup',e=>keys[e.code]=false);document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);press(b.dataset.key)});for(const type of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,()=>keys[b.dataset.key]=false)});window.addEventListener('blur',()=>{keys={};if(screen==='play'&&!paused)pauseGame()});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys={};save();if(screen==='play'&&!paused)pauseGame()}});window.addEventListener('beforeunload',save);canvas.addEventListener('pointerdown',()=>canvas.focus({preventScroll:true}));
readStorage();renderSlots();switchScreen('title');function frame(now){const dt=Math.min((now-last)/1000||0,.033);last=now;update(dt);if(screen==='play')drawWorld();if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}requestAnimationFrame(frame)}requestAnimationFrame(frame);
